// --- CALCULATE AREA --- //
// Display the score of each player on hex?
// Read the game window on the background and if the pixel matches the player
// colour add to that player's score
const unsigned char font[10][5] = {
    {0x1F, 0x11, 0x11, 0x11, 0x1F},  // 0
    {0x04, 0x0C, 0x04, 0x04, 0x1F},  // 1
    {0x1F, 0x01, 0x1F, 0x10, 0x1F},  // 2
    {0x1F, 0x01, 0x1F, 0x01, 0x1F},  // 3
    {0x11, 0x11, 0x1F, 0x01, 0x01},  // 4
    {0x1F, 0x10, 0x1F, 0x01, 0x1F},  // 5
    {0x1F, 0x10, 0x1F, 0x11, 0x1F},  // 6
    {0x1F, 0x01, 0x02, 0x04, 0x08},  // 7
    {0x1F, 0x11, 0x1F, 0x11, 0x1F},  // 8
    {0x1F, 0x11, 0x1F, 0x01, 0x1F}   // 9
};

void draw_digit(int x, int y, int digit, short color, short* buf) {
  for (int row = 0; row < 5; row++) {
    unsigned char row_data = font[digit][row];

    for (int col = 0; col < 5; col++) {
      // Check if the bit is set (MSB is leftmost)
      if (row_data & (1 << (4 - col))) {
        // Calculate the top-left corner of the scaled "pixel" block
        // Width multiplier = 2, Height multiplier = 3
        int base_x = x + col * 2;
        int base_y = y + row * 3;

        // Fill a 2-pixel wide by 3-pixel high rectangle
        for (int dx = 0; dx < 2; dx++) {
          for (int dy = 0; dy < 3; dy++) {
            plot_pixel(base_x + dx, base_y + dy, color, buf);
          }
        }
      }
    }
  }
}

void displayScore(struct player* p1, struct player* p2, short* back_buf_ptr) {
  int padding = 15;
  int Bottom_Left_Y = 213;

  // --- Player 1 Score ---
  calculateArea(p1);
  int p1_score_disp = p1->score / 10;
  int p1_thousands = p1_score_disp / 1000;
  int p1_hundreds = (p1_score_disp % 1000) / 100;
  int p1_tens = (p1_score_disp % 100) / 10;
  int p1_ones = p1_score_disp % 10;

  int p1_X = 10;

  // Clear P1 area
  for (int i = 0; i < 4; i++) {
    for (int y = Bottom_Left_Y; y < Bottom_Left_Y + 15; y++) {
      for (int x = p1_X + i * padding; x < p1_X + (i + 1) * padding; x++) {
        plot_pixel(x, y, background[y * SCREEN_W + x], back_buf_ptr);
      }
    }
  }

  // Draw P1 digits
  if (p1_thousands != 0)
    draw_digit(p1_X, Bottom_Left_Y, p1_thousands, p1->colour, back_buf_ptr);
  if (p1_thousands != 0 || p1_hundreds != 0)
    draw_digit(p1_X + padding, Bottom_Left_Y, p1_hundreds, p1->colour,
               back_buf_ptr);
  if (p1_thousands != 0 || p1_hundreds != 0 || p1_tens != 0)
    draw_digit(p1_X + padding * 2, Bottom_Left_Y, p1_tens, p1->colour,
               back_buf_ptr);

  draw_digit(p1_X + padding * 3, Bottom_Left_Y, p1_ones, p1->colour,
             back_buf_ptr);

  // --- Player 2 Score ---
  calculateArea(p2);
  int p2_score_disp = p2->score / 10;
  int p2_thousands = p2_score_disp / 1000;
  int p2_hundreds = (p2_score_disp % 1000) / 100;
  int p2_tens = (p2_score_disp % 100) / 10;
  int p2_ones = p2_score_disp % 10;

  // Positioned on the right (320 - 60px for digits - 10px margin)
  int p2_X = 253;

  // Clear P2 area
  for (int i = 0; i < 4; i++) {
    for (int y = Bottom_Left_Y; y < Bottom_Left_Y + 15; y++) {
      for (int x = p2_X + i * padding; x < p2_X + (i + 1) * padding; x++) {
        plot_pixel(x, y, background[y * SCREEN_W + x], back_buf_ptr);
      }
    }
  }

  // Draw P2 digits
  if (p2_thousands != 0)
    draw_digit(p2_X, Bottom_Left_Y, p2_thousands, p2->colour, back_buf_ptr);
  if (p2_thousands != 0 || p2_hundreds != 0)
    draw_digit(p2_X + padding, Bottom_Left_Y, p2_hundreds, p2->colour,
               back_buf_ptr);
  if (p2_thousands != 0 || p2_hundreds != 0 || p2_tens != 0)
    draw_digit(p2_X + padding * 2, Bottom_Left_Y, p2_tens, p2->colour,
               back_buf_ptr);

  draw_digit(p2_X + padding * 3, Bottom_Left_Y, p2_ones, p2->colour,
             back_buf_ptr);
}

void calculateArea(struct player* p) {
  p->score = 0;  // reset score before recounting

  for (int y = WINDOW_START_Y; y < WINDOW_END_Y; y++) {
    for (int x = WINDOW_START_X; x < WINDOW_END_X; x++) {
      if (p->colour == background[y * SCREEN_W + x]) {
        p->score += 1;
      }
    }
  }
}

// --- Restart --- //
void restart(short* back_buf_ptr) {
  clearPaintEvent(back_buf_ptr);
  clearPaintEvent(pixel_buffer_start);
  draw_background(back_buf_ptr);
  progressx = 77;
  // gameEnd = true;
  eventFlag = false;
}

// --- INTERRUPTS --- // MIGHT NOT NEED
#define clock_rate 100000000
#define quarter_clock clock_rate / 4

// Interrupt Functions
static void handler(void) __attribute__((interrupt("machine")));
void set_mtimer(void);
void mtimer_ISR(void);

// Volatile interrupts variables

// Interrupt handler
void handler(void) {
  int mcause_value;
  __asm__ volatile("csrr %0, mcause" : "=r"(mcause_value));
  if (mcause_value == 0x80000007)  // machine timer
    mtimer_ISR();
}

// Interrupt Service Routines
typedef long long int64;

// Timer
void mtimer_ISR(void) {
  volatile unsigned int* mtime_ptr = (unsigned int*)0xFF202100;
  int64 mtimecmp64;
  mtimecmp64 = *(mtime_ptr + 3);  // read high word of 64-bit register
  mtimecmp64 = (mtimecmp64 << 32) | *(mtime_ptr + 2);   // read low word
  mtimecmp64 = mtimecmp64 + (int64)quarter_clock;       // adjus timeout
  *(mtime_ptr + 2) = (unsigned int)mtimecmp64;          // store low word
  *(mtime_ptr + 3) = (unsigned int)(mtimecmp64 >> 32);  // store high word
}

// Configure the Nios V machine timer
void set_mtimer(void) {
  volatile int* mtime_ptr = (int*)0xFF202100;
  unsigned int mtime_h, mtime_l, carry, mtimecmp_l;
  do {
    mtime_h = *(mtime_ptr + 1);  // read mtime high word
    mtime_l = *(mtime_ptr);      // read mtime low word
  } while (*(mtime_ptr + 1) != mtime_h);
  mtimecmp_l = mtime_l + quarter_clock;  // add to current time
  carry = mtimecmp_l < mtime_l ? 1 : 0;  // check for carry-out
  *(mtime_ptr + 2) = mtimecmp_l;         // set mtimecmp low word
  *(mtime_ptr + 3) = mtime_h + carry;    // set mtimecmp high word
}

void read_ps2key(struct player* p1, struct player* p2,short* back_buf_ptr)
{
    volatile int *PS2_ptr = (int *)PS2_BASE;
    volatile int *LED_ptr = (int *)LED_BASE;

    static int got_f0 = 0;
    static int led_state = 0;

    while (1)
    {
        int data = *PS2_ptr;
        int rvalid = (data >> 15) & 0x1;

        if (!rvalid)
            break;

        unsigned char byte = data & 0xFF;

        if (byte == 0xF0)
        {
            got_f0 = 1; // key release
        }
        else
        {
            if (got_f0)
            {
                got_f0 = 0; // ignore release
            }
            else
            {
                switch (byte)
                {
                    //player 1  ------------------
                    case 0x1D: // W, move up
                        update_player_movement(p1, 0, -1);
                        led_state ^= (1 << 0);
                        break;

                    case 0x1B: // S, move down
                        update_player_movement(p1, 0, 1);
                        led_state ^= (1 << 1);
                        break;

                    case 0x1C: // A, move left
                        update_player_movement(p1, -1, 0);
                        led_state ^= (1 << 2);
                        break;

                    case 0x23: // D, move right
                        update_player_movement(p1, 1, 0);
                        led_state ^= (1 << 3);
                        break;

                    case 0x21: // C, shoot
                        shoot(p1, back_buf_ptr);
                        led_state ^= (1 << 4);
                        break;


                    //player 2  ------------------
                    case 0x43: // I, move up
                        update_player_movement(p2, 0, -1);
                        led_state ^= (1 << 5);
                        break;

                    case 0x3B: // J, move left
                        update_player_movement(p2, -1, 0);
                        led_state ^= (1 << 6);
                        break;

                    case 0x42: // K, move down
                        update_player_movement(p2, 0, 1);
                        led_state ^= (1 << 7);
                        break;

                    case 0x4B: // L, move right
                        update_player_movement(p2, 1, 0);
                        led_state ^= (1 << 8);
                        break;

                    case 0x31: // N, shoot
                        shoot(p2, back_buf_ptr);
                        led_state ^= (1 << 9);
                        break;

                    default:
                        break;
                }

                *LED_ptr = led_state;
            }
        }
    }
}

// --- MAIN PROGRAM -- //
int main(void) {
  // --- Graphics --- //
  volatile int* pixel_ctrl_ptr = (int*)0xFF203020;
  short int Buffer1[240][512];
  short int Buffer2[240][512];

  short int current_frame[SCREEN_H][SCREEN_W];
  short int next_frame[SCREEN_H][SCREEN_W];
  // declare other variables(not shown)

  /* set front pixel buffer to Buffer1 */
  *(pixel_ctrl_ptr + 1) = (int)&Buffer1;
  wait_for_vsync();

  pixel_buffer_start = *pixel_ctrl_ptr;
  draw_background(pixel_buffer_start);

  short* back_buf_ptr = (short*)*(pixel_ctrl_ptr + 1);
  pixel_buffer_start = *(pixel_ctrl_ptr + 1);
  draw_background(back_buf_ptr);

  // --- Set up players --- //

  // x   y  old_x old_y dx dy colour score player_radius, shoot_radius
  struct player p1 = {160, 120, 160, 120, 1, 0, 0xF800, 0, 15, 7, 0};
  struct player p2 = {100, 100, 100, 100, 0, 1, 0x001F, 0, 15, 7, 0};

  // --- Set up pointers --- //
  volatile int* mtime_ptr = (int*)0xFF202100;
  volatile int* LEDR_ptr = (int*)0xFF200000;
  volatile int* HEX3_HEX0_ptr = (int*)0xFF200020;
  volatile int* characterBuffer_ptr = (int*)0x09000000;

  set_mtimer();
  int mstatus_value, mtvec_value, mie_value;
  mstatus_value = 0b1000;  // interrupt bit mask
  // disable interrupts
  __asm__ volatile("csrc mstatus, %0" ::"r"(mstatus_value));
  mtvec_value = (int)&handler;  // set trap address
  __asm__ volatile("csrw mtvec, %0" ::"r"(mtvec_value));
  // disable all interrupts that are currently enabled
  __asm__ volatile("csrr %0, mie" : "=r"(mie_value));
  __asm__ volatile("csrc mie, %0" ::"r"(mie_value));
  mie_value = 0x50088;  // KEY, itimer, mtimer, SW interrupts
  // set interrupt enables
  __asm__ volatile("csrs mie, %0" ::"r"(mie_value));
  // enable Nios V interrupts
  __asm__ volatile("csrs mstatus, %0" ::"r"(mstatus_value));

  // write a character
  *characterBuffer_ptr = 'A';

  // -- MAIN GAME LOOP -- //
  while (!gameEnd) {
    // If the game is over light up an LED
    if (progressx >= 242) {
      *LEDR_ptr = 0x1;
      gameEnd = true;
    }

    // Trigger random events at specific times
    if (progressx >= 160 && eventFlag == false) {
      // raise flag
      eventFlag = true;
      // run random event
      int randomEvent = chooseRandomEvent();
      printf("%d random event number\n", randomEvent);
      *LEDR_ptr = 0x10;

      // --- TEST CLEAR PAINT EVENT --- //
      clearPaintEvent(back_buf_ptr);
      for (int y = 38; y < 176; y++) {
        for (int x = 23; x < 295; x++) {
          plot_pixel(x, y, background[y * SCREEN_W + x], back_buf_ptr);
        }
      }
      wait_for_vsync();
      pixel_buffer_start = *(pixel_ctrl_ptr + 1);

      for (int y = 38; y < 176; y++) {
        for (int x = 23; x < 295; x++) {
          plot_pixel(x, y, background[y * SCREEN_W + x], pixel_buffer_start);
        }
      }
      
      // --- //


      // TEST INCREASE AND DECREASE PAINT SIZE 
      increasePaintbrush(&p1, &p2); 
      decreasePaintbrush(&p1, &p2); 

      // --- //


    }

    // --- PLAYER UPDATES --- //

    volatile int* sw_ptr = (int*)SW_BASE;
    int sw_value = *sw_ptr;
    // Update player scores

    // Read keyboard input for player 1
    read_switch_input(back_buf_ptr);

    read_ps2key(&p1, &p2, back_buf_ptr);

    // Update positions (old positions are saved inside update_player_position)
    update_player_position(&p1);
    update_player_position(&p2);

    // Restore background where players WERE (old positions)
    restore_old_player_area(&p1, back_buf_ptr);
    restore_old_player_area(&p2, back_buf_ptr);

    displayScore(&p1, &p2, back_buf_ptr);

    // Draw players at NEW positions
    draw_player(&p1, back_buf_ptr);
    draw_player(&p2, back_buf_ptr);

    // Update progress bar
    progressx = progressx + 0.02;
    updateProgressBar(back_buf_ptr);

    // Wait for vertical sync and swap buffers
    wait_for_vsync();
    pixel_buffer_start = *(pixel_ctrl_ptr + 1);
  }
}
